(() => {
'use strict';
const D=window.BARLEMICA_GAME, KEY='barlemica-game-v2', VERSION=2, B=window.BarlemicaBottles;
const $=s=>document.querySelector(s), clone=x=>JSON.parse(JSON.stringify(x)), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let legacy=null,animationRows=null,effectTimer=null,resultRows=null,correctionPending=null,inventoryPending=null;
let inventoryDraft={rules:clone(B.DEFAULT_RULES),stock:Object.fromEntries(B.DENOMS.map(d=>[d.id,null]))};
let state=null,saved=null,storageOK=true,draft=['Команда 1','Команда 2','Команда 3'],toastId,clock=null;
try{saved=JSON.parse(localStorage.getItem(KEY)||'null');legacy=JSON.parse(localStorage.getItem('barlemica-game-v1')||'null');}catch(e){storageOK=false;}
const qById=Object.fromEntries(D.questions.map(q=>[q.id,q]));
const team=id=>state.teams.find(t=>t.id===id), question=()=>qById[state.currentQuestionId];
const fmt=n=>Number(n).toLocaleString('ru-RU');
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastId);toastId=setTimeout(()=>$('#toast').style.display='none',4200);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));saved=clone(state);}catch(e){if(storageOK)toast('Автосохранение недоступно. Сохраняйте резервные копии через меню.');storageOK=false;}}
function snapshot(){const s=clone(state);delete s.history;delete s.future;s.physicalLog=[];s.timerRunning=false;return s;}
function action(label,fn){const before=snapshot(),history=state.history,future=state.future;try{fn();B.reconcile(state);state.history.push({label,before,after:snapshot()});state.history=state.history.slice(-20);state.future=[];persist();render();if(animationRows){showResult(animationRows);animationRows=null;}}catch(e){state={...before,history,future};animationRows=null;toast(e.message||'Действие не выполнено');}}
function stopClock(){clearInterval(clock);clock=null;}
function undo(){if(!state?.history.length)return toast('Нет действий для отмены');stopClock();skipEffect();const actual=clone(state.physicalBank),physicalLog=clone(state.physicalLog),h=state.history.pop(),history=state.history,future=state.future;future.push(h);state={...clone(h.before),history,future};restoreActual(actual,physicalLog,h.label);persist();render();toast('Отменено: '+h.label+'. Проверьте физическую сверку.');}
function redo(){if(!state?.future.length)return;stopClock();skipEffect();const actual=clone(state.physicalBank),physicalLog=clone(state.physicalLog),h=state.future.pop(),future=state.future,history=state.history;history.push(h);state={...clone(h.after),history,future};restoreActual(actual,physicalLog,h.label);persist();render();toast('Повторено: '+h.label+'. Физические предметы не перемещаются автоматически.');}
function icon(name){const paths={palette:'<circle cx="12" cy="12" r="9"/><circle cx="8" cy="8" r="1"/><circle cx="14" cy="6" r="1"/><circle cx="6" cy="13" r="1"/><path d="M21 12c-5-3-9 1-7 4 2 4-2 6-5 4"/>',martini:'<path d="M3 3h18l-9 10zM12 13v8M7 21h10M8 1l5 7"/>',wine:'<path d="M7 3h10l1 7a6 6 0 0 1-12 0zM12 16v5M8 21h8M6 8h12"/>',coffee:'<path d="M4 8h13v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4zM17 9h2a3 3 0 0 1 0 6h-2M7 2v3M11 2v3M15 2v3"/>',utensils:'<path d="M5 2v7M2 2v5a3 3 0 0 0 6 0V2M5 10v12M18 2c-4 3-5 7-4 11h5M19 2v20"/>',smile:'<circle cx="12" cy="12" r="9"/><path d="M8 14q4 5 8 0M8 8h.01M16 8h.01"/>',default:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>'};return '<svg viewBox="0 0 24 24" aria-hidden="true">'+(paths[name]||paths.default)+'</svg>';}
function header(){return `<header><div class="brand" aria-label="СВОЯ BARLEMICA"><div class="brand-title"><span class="brand-own">СВОЯ</span>${wordmark()}</div><span class="brand-sub">2026</span></div><div class="header-actions"><button data-act="legend" class="legend-button">Легенда</button>${state?`<button data-act="physical" class="bank-button">Банк <span class="pending-count">${state.teams.filter(t=>state.physicalBank[t.id].pending).length}</span></button>`:''}<button class="icon-button" data-act="fullscreen" aria-label="Полноэкранный режим" title="Полный экран · F">⛶</button><button class="icon-button" data-act="menu" aria-label="Меню ведущего" title="Меню ведущего">☰</button></div></header>`;}
function footer(){return `<footer class="footer"><span>СВОЯ BARLEMICA / 2026 · ${state?(storageOK?'Сохранено на этом устройстве':'Состояние только в памяти'):'Интеллектуальное барное шоу'}</span><span class="shortcuts">${state?'<span class="key">Space</span> ответ　<span class="key">T</span> таймер　<span class="key">U</span> отмена　':''}<span class="key">F</span> полный экран</span></footer>`;}
function startView(){return `<main class="welcome fade"><section><div class="eyebrow">25 ноября / фестиваль Barlemica 2026</div><h1><span class="own-title">СВОЯ</span>${wordmark()}</h1><p class="intro">Хорошие вопросы.<br>Яркие команды. Настоящий азарт.</p><div class="start-cue"><span class="bottle-mark"></span>Очки на экране, Royal Cane — на столе.</div><button data-act="legend">Как считаем бутылки →</button></section><section class="setup"><div class="setup-heading"><h2>Кто сегодня играет?</h2><span class="count">2–6 команд</span></div><div id="team-fields">${draft.map((name,i)=>`<label class="team-input"><span class="team-number">0${i+1}</span><input data-team="${i}" aria-label="Название команды ${i+1}" maxlength="60" value="${esc(name)}">${draft.length>2?`<button data-act="remove-team" data-i="${i}" aria-label="Убрать команду ${i+1}">×</button>`:''}</label>`).join('')}</div><button class="add-team" data-act="add-team" ${draft.length>=6?'disabled':''}>＋ Добавить команду</button><button class="stock-start" data-act="inventory">Настроить физический реквизит</button>${saved?'<button class="resume-button" data-act="resume">Продолжить сохранённую игру ↗</button>':''}${legacy?'<button class="resume-button" data-act="legacy">Обнаружено сохранение v1 · перенос</button>':''}<button class="primary start-button" data-act="start"><span>Начать игру</span><span>→</span></button><p class="setup-note">Работает без интернета. Очки — источник истины.<br>Выдачу бутылок подтверждает оператор.</p></section></main><div class="features"><div class="feature"><strong>3</strong><span>раунда</span></div><div class="feature"><strong>90</strong><span>точных вопросов</span></div><div class="feature"><strong>18</strong><span>категорий</span></div><div class="feature"><strong>50</strong><span>очков — шаг ставки</span></div></div>`;}
function scores(){return `<section class="scores" style="--team-count:${state.teams.length}" aria-label="Счёт команд">${state.teams.map((t,i)=>{const b=state.physicalBank[t.id];return `<button class="score-card ${t.id===state.activeTeamId?'active':''} ${t.score<0?'debt':''}" data-act="active-team" data-id="${esc(t.id)}" ${state.currentQuestionId?'disabled':''} aria-label="${esc(t.name)}, ${t.score} очков. ${b.pending?'Ожидает физической сверки. ':''}Передать право выбора"><div class="score-top"><span>${t.id===state.activeTeamId?'● ВЫБИРАЕТ':'КОМАНДА 0'+(i+1)}</span><span class="physical-status ${b.pending?'pending':''}">${b.pending?'Ожидает выдачи':'✓ Сверено'}</span></div><div class="score-name" title="${esc(t.name)}">${esc(t.name)}</div><div class="score-value" data-score-team="${esc(t.id)}">${t.score<0?'−'+fmt(Math.abs(t.score)):fmt(t.score)}</div>${t.score<0?'<span class="debt-tag">ДОЛГ</span>':''}</button>`;}).join('')}</section>`;}
function boardView(){const round=D.rounds[state.currentRound-1],n=state.answeredIds.filter(id=>qById[id].round===state.currentRound).length;return `<main class="board-view fade"><div class="board-heading"><div><div class="eyebrow">Раунд ${state.currentRound} из 3</div><h1>${esc(round.title.charAt(0)+round.title.slice(1).toLowerCase())}</h1></div><div class="round-info"><div class="round-tabs" aria-label="Раунды">${[1,2,3].map(r=>`<button class="round-tab ${r===state.currentRound?'current':''}" data-act="round" data-r="${r}" aria-label="Перейти в раунд ${r}">${r}</button>`).join('')}</div><div><div class="progress-label">Сыграно <b>${n}</b> / 30</div><div class="progress-track"><i style="width:${n/30*100}%"></i></div></div></div></div><section class="board" aria-label="Игровое поле: шесть строк категорий">${D.categories.filter(c=>c.round===state.currentRound).map(c=>`<div class="category"><div class="category-title" title="${esc(c.title)}"><span>${esc(c.title)}</span></div>${D.questions.filter(q=>q.round===state.currentRound&&q.category_id===c.id).map(q=>{const done=state.answeredIds.includes(q.id);return `<button class="cell ${done?'played':''}" data-act="question" data-id="${q.id}" ${done?'disabled':''} aria-label="${esc(c.title)}, ${q.points} очков${done?', сыграно':''}">${done?'<span>—</span>':`<span>${fmt(q.points)}</span><span class="bottle-mark" aria-hidden="true"></span>`}</button>`;}).join('')}</div>`).join('')}</section>${scores()}<div class="board-bottom"><span class="hint">${esc(team(state.activeTeamId).name)} выбирает вопрос</span><div class="button-row"><button data-act="undo" ${state.history.length?'':'disabled'}>↶ Отменить</button><button data-act="physical">Сверка бутылок</button>${state.currentRound<3?`<button data-act="next-round">К ${state.currentRound+1}-му раунду →</button>`:''}<button data-act="finish">${state.currentRound===2?'Завершить игру сейчас':'Итоги'} ↗</button></div></div></main>`;}
function timerHTML(){return `<div class="timer"><div id="timer-value" class="timer-number ${state.timerRemaining===0?'expired':''}" aria-live="polite">${state.timerRemaining===0?'Время!':String(state.timerRemaining).padStart(2,'0')}</div><button data-act="timer" aria-label="Старт или пауза таймера" id="timer-toggle">${state.timerRunning?'Ⅱ Пауза':'▷ Старт'}</button><button data-act="timer-reset" aria-label="Перезапустить таймер">↻</button><button data-act="timer-add" aria-label="Добавить десять секунд">+10 с</button></div>`;}
function missing(){return `<div class="missing-media"><svg viewBox="0 0 80 60" aria-hidden="true"><rect x="2" y="2" width="76" height="56" rx="5"/><path d="m4 50 22-24 17 18 12-13 23 23"/><circle cx="55" cy="16" r="6"/></svg><b>МЕДИА НЕ ЗАГРУЖЕНО</b>Изображение не подготовлено.<br>Ведущий может прочитать вопрос.</div>`;}
function questionView(){const q=question(),f=state.specialFlow,responder=team(f.responderId),pending=state.teams.filter(t=>state.physicalBank[t.id].pending).length;return `<main class="question-view fade"><div class="question-top"><div class="question-category">Раунд ${q.round} / ${esc(q.category)}<span class="question-price"><span class="bottle-mark" aria-hidden="true"></span>${fmt(f.stake||q.points)} очков</span></div><div class="responding"><span class="pill">${esc(responder?.name||'Перехват')}</span>${pending?`<button class="pending-hint" data-act="physical">Ожидает выдачи: ${pending}</button>`:''}</div></div><div class="question-body ${q.media_type==='artwork'?'with-art':''}"><div class="question-copy">${q.media_type==='emoji'?`<div class="emoji" aria-label="Ребус из эмодзи">${esc(q.media_text)}</div>`:''}<h1 class="question-text">${esc(q.question)}</h1>${state.revealed?`<div class="answer"><div class="answer-label">Правильный ответ</div>${esc(q.answer)}</div>`:''}</div>${q.media_type==='artwork'?`<div class="art-frame"><img src="assets/art/${q.id.toLowerCase()}.jpg" alt="Изображение к вопросу" id="question-art"></div>`:''}</div><div class="question-tools">${timerHTML()}<div class="button-row">${state.revealed?'<button data-act="host-note">Заметка ведущему</button>':`<button class="primary" data-act="reveal">Показать ответ <span class="key">Space</span></button>`}</div></div>${state.revealed?judgingHTML(q,f):''}</main>`;}
function judgingHTML(q,f){if(f.stage==='steal-offer')return `<section class="judging"><div class="judging-label">${f.firstResult==='wrong'?'Неверный ответ':'Без ответа'}. Можно предложить один перехват за ${fmt(q.points/2)} очков.</div><div class="judging-actions">${state.teams.filter(t=>t.id!==f.openerId).map(t=>`<button data-act="steal" data-id="${t.id}">Перехват · ${esc(t.name)}</button>`).join('')}<button class="primary" data-act="complete">Завершить вопрос →</button></div></section>`;return `<section class="judging"><div class="judging-label">${f.stage==='steal'?'ПЕРЕХВАТ · половина номинала':'ОЦЕНКА ОТВЕТА'} · ${esc(team(f.responderId).name)} · ${fmt(f.stage==='steal'?q.points/2:f.stake||q.points)} очков</div><div class="judging-actions"><button class="positive" data-act="judge" data-result="correct">✓ Верно</button><button class="negative" data-act="judge" data-result="wrong">× Неверно</button><button data-act="judge" data-result="pass">Без ответа</button></div></section>`;}
function specialView(){const q=question(),f=state.specialFlow;if(f.stage==='bag')return `<main class="special-view fade"><section class="special-card"><div class="eyebrow">Специальный вопрос / ${fmt(q.points)} очков</div><div class="special-symbol">♢</div><h1>СИРОП В МЕШКЕ</h1><p>${esc(team(f.openerId).name)}, передайте вопрос другой команде.<br>Она отвечает за полный номинал. Перехвата нет.<br>Право следующего выбора остаётся у вас.</p><div class="team-options">${state.teams.filter(t=>t.id!==f.openerId).map(t=>`<button class="primary" data-act="bag-to" data-id="${t.id}">${esc(t.name)} →</button>`).join('')}</div><button data-act="cancel-question">Отменить до показа</button></section></main>`;return `<main class="special-view fade"><section class="special-card"><div class="eyebrow">Специальный вопрос / Аукцион</div><div class="special-symbol">↗</div><h1>ВОТ ТАКАЯ ИГРА,<br>СОБАЧКА</h1><p>Первую ставку может сделать ${esc(team(f.openerId).name)}.<br>Шаг ставки — 50 очков. Ставка не больше положительного баланса.<br>Победитель отвечает на сумму ставки. Перехвата нет.</p><div class="bid-leader">${f.leaderId?`${esc(team(f.leaderId).name)} · ${fmt(f.stake)} очков`:'Пока нет ставок'}</div>${timerHTML()}<form id="bid-form" class="auction-row"><select id="bid-team" aria-label="Команда для ставки">${state.teams.filter(t=>t.score>0).map(t=>`<option value="${t.id}" ${t.id===f.openerId?'selected':''}>${esc(t.name)} · ${fmt(t.score)}</option>`).join('')}</select><input id="bid-value" type="number" min="${(f.stake||0)+state.rules.auctionStep}" step="${state.rules.auctionStep}" placeholder="Ставка" aria-label="Сумма ставки" required><button class="primary" type="submit">Повысить ↑</button></form><div class="bid-list">${f.bids.map(b=>`${esc(team(b.teamId).name)} — ${fmt(b.amount)}`).join('<br>')}</div><div class="button-row" style="justify-content:center;margin-top:20px"><button data-act="cancel-question">Отменить аукцион</button><button class="primary" data-act="auction-end">${f.leaderId?'Завершить торги →':'Играть за номинал →'}</button></div></section></main>`;}
function resultsView(){const ranked=[...state.teams].sort((a,b)=>b.score-a.score);return `<main class="ranking fade"><div class="eyebrow">BARLEMICA / ИТОГИ ВЕЧЕРА</div><h1>Хорошая была игра.</h1><div>${ranked.map(t=>{const pos=ranked.findIndex(r=>r.score===t.score)+1,tie=ranked.filter(r=>r.score===t.score).length>1;return `<div class="rank-row"><span class="rank-pos">${String(pos).padStart(2,'0')}</span><div class="rank-team">${esc(t.name)}${tie?'<div class="tie">Ничья · разделённое место</div>':''}</div><span class="rank-score">${fmt(t.score)}</span></div>`;}).join('')}</div><p class="small">Сыграно ${state.answeredIds.length} из 90 вопросов. Незаданные вопросы остаются на поле.</p><div class="button-row" style="margin-top:25px"><button class="primary" data-act="export-results">Скачать результаты ↓</button><button data-act="return-board">Вернуться к полю</button><button data-act="tie-break">Нейтральный тай-брейк</button></div></main>`;}
function render(){skipEffect();const focused=document.activeElement?.id;$('#app').innerHTML=`<div class="shell ${state?'is-game':'is-start'}">${header()}${!state?startView():state.view==='results'?resultsView():state.currentQuestionId?(state.specialFlow.stage==='bag'||state.specialFlow.stage==='auction'?specialView():questionView()):boardView()}${footer()}</div>`;const img=$('#question-art');if(img)img.onerror=()=>{img.parentElement.innerHTML=missing();};document.querySelectorAll('[data-brand]').forEach(img=>{img.onload=()=>{img.hidden=false;img.parentElement.classList.add('has-logo');img.closest('.brand-title')?.classList.add('with-logo');img.parentElement.querySelector('.brand-fallback').hidden=true;img.parentElement.querySelector('.brand-note').hidden=true;};img.onerror=()=>{if(!img.dataset.triedPng){img.dataset.triedPng='1';img.src='assets/brand/barlemica-logo.png';}else img.remove();};if(img.complete&&img.naturalWidth)img.onload();});document.querySelectorAll('[data-bottle]').forEach(img=>{img.onerror=()=>{img.hidden=true;img.nextElementSibling.hidden=false;};});if(focused&&$('#'+focused))$('#'+focused).focus();}
function dialog(title,body){const d=$('#dialog');d.classList.toggle('wide',/physical-grid|legend-grid|stock-rows|data-result-panel/.test(body));d.classList.toggle('result-dialog',body.includes('data-result-panel'));d.classList.toggle('single-result',body.includes('data-result-panel')&&!body.includes('two-teams'));d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-act="close-dialog" aria-label="Закрыть диалог">×</button></div>${body}`;d.querySelectorAll('[data-bottle]').forEach(img=>{img.onerror=()=>{img.hidden=true;img.nextElementSibling.hidden=false;};});if(!d.open)d.showModal();}
function close(){const d=$('#dialog');d.close();if(d.classList.contains('result-dialog')){skipEffect();resultRows=null;}}
function confirmDialog(title,text,act,extra=''){dialog(title,`<p>${text}</p><div class="button-row"><button class="primary" data-act="${act}" ${extra}>Подтвердить</button><button data-act="close-dialog">Отмена</button></div>`);}
function readDraft(){document.querySelectorAll('[data-team]').forEach(el=>draft[Number(el.dataset.team)]=el.value);}
function newGame(){stopClock();state={schemaVersion:VERSION,rulesVersion:'2.0',rules:clone(inventoryDraft.rules),physicalStock:clone(inventoryDraft.stock),physicalBank:{},physicalLog:[],appliedTransactions:{},serial:0,startedAt:new Date().toISOString(),teams:draft.map((name,i)=>({id:'team-'+(i+1),name:name.trim()||'Команда '+(i+1),score:0})),currentRound:1,activeTeamId:'team-1',answeredIds:[],currentQuestionId:null,revealed:false,timerRemaining:20,timerRunning:false,specialFlow:null,scoreLog:[],history:[],future:[],view:'board'};B.reconcile(state);persist();close();render();}
function openQuestion(id){if(state.currentQuestionId||state.answeredIds.includes(id))return;action('Открытие вопроса',()=>{const q=qById[id];state.currentQuestionId=id;state.revealed=false;state.timerRemaining=q.timer_seconds;state.timerRunning=false;state.specialFlow={kind:q.special||'normal',stage:'answer',openerId:state.activeTeamId,responderId:state.activeTeamId,stake:q.points,bids:[],leaderId:null,decisions:[],actionId:'q:'+q.id+':'+(++state.serial)};if(q.special==='bag')state.specialFlow.stage='bag';if(q.special==='auction'){if(state.teams.some(t=>t.score>=state.rules.auctionMin)){state.specialFlow.stage='auction';state.specialFlow.stake=0;state.timerRemaining=30;}else{state.specialFlow.kind='normal';toast('Нет положительного счёта. Играем обычный вопрос за номинал.');}}});}
function finalize(){const f=state.specialFlow,q=question();if(state.appliedTransactions[q.id])throw new Error('Этот вопрос уже оценён');const rows=[];for(const d of f.decisions){if(!B.validAmount(d.delta))throw new Error('Начисление должно быть кратно 50');const t=team(d.teamId),before=t.score,after=before+d.delta;if(!B.validAmount(after))throw new Error('Некорректный баланс');t.score=after;const row={questionId:q.id,actionId:f.actionId,teamId:t.id,basePoints:q.points,kind:d.kind,stake:f.kind==='auction'?f.stake:null,result:d.result,delta:d.delta,before,after,timestamp:new Date().toISOString()};state.scoreLog.push(row);rows.push({...row,name:t.name});}state.appliedTransactions[q.id]=f.actionId;state.answeredIds.push(q.id);state.activeTeamId=f.kind==='normal'?(f.correctTeamId||f.openerId):f.openerId;state.currentQuestionId=null;state.specialFlow=null;state.revealed=false;state.timerRunning=false;animationRows=rows;}
function judge(result){if(!state?.currentQuestionId||!state.revealed||!['correct','wrong','pass'].includes(result))return;const f=state.specialFlow;if(!['answer','steal'].includes(f.stage))return;stopClock();action('Оценка ответа: '+result,()=>{const q=question(),f=state.specialFlow,kind=f.stage==='steal'?'steal':f.kind==='normal'?'regular':f.kind,amount=f.stage==='steal'?q.points/2:(f.stake||q.points),delta=result==='correct'?amount:result==='wrong'?-amount:0;f.decisions.push({teamId:f.responderId,delta,result,kind});state.timerRunning=false;if(result==='correct'){f.correctTeamId=f.responderId;finalize();}else if(f.kind==='normal'&&f.stage!=='steal'){f.firstResult=result;f.stage='steal-offer';}else finalize();});}
function syncTimer(){const el=$('#timer-value');if(el){el.textContent=state.timerRemaining?String(state.timerRemaining).padStart(2,'0'):'Время!';el.classList.toggle('expired',state.timerRemaining===0);}const btn=$('#timer-toggle');if(btn)btn.textContent=state.timerRunning?'Ⅱ Пауза':'▷ Старт';}
function toggleTimer(){if(!state?.currentQuestionId)return;const stage=state.specialFlow.stage;if(!['answer','steal','auction'].includes(stage))return;if(!state.timerRemaining)return toast('Перезапустите таймер или добавьте время');action('Старт / пауза таймера',()=>{state.timerRunning=!state.timerRunning;});stopClock();if(state.timerRunning){let last=Date.now();clock=setInterval(()=>{if(!state?.timerRunning){stopClock();return;}const now=Date.now(),elapsed=Math.floor((now-last)/1000);if(elapsed<1)return;last+=elapsed*1000;state.timerRemaining=Math.max(0,state.timerRemaining-elapsed);if(!state.timerRemaining){state.timerRunning=false;stopClock();}persist();syncTimer();},200);}}
function reveal(){if(!state?.currentQuestionId||state.revealed||!['answer','steal'].includes(state.specialFlow.stage))return;stopClock();action('Раскрытие ответа',()=>{state.revealed=true;state.timerRunning=false;});}
function bid(){if(state.timerRemaining===0)return toast('Время торгов вышло. Завершите аукцион.');const id=$('#bid-team').value,amount=Number($('#bid-value').value),f=state.specialFlow;if(!team(id)||!B.validAmount(amount)||amount<state.rules.auctionMin||amount%state.rules.auctionStep!==0||amount>team(id).score||amount<(f.stake||0)+state.rules.auctionStep)return toast('Ставка — от 50 очков, кратна 50, выше лидера и не больше баланса');action('Ставка на аукционе',()=>{f.stake=amount;f.leaderId=id;f.bids.push({teamId:id,amount});});$('#bid-value')?.focus();}
function auctionEnd(){if(state.specialFlow.stage!=='auction')return;stopClock();action('Завершение аукциона',()=>{const f=state.specialFlow;if(!f.leaderId){f.kind='normal';f.responderId=f.openerId;f.stake=question().points;}else f.responderId=f.leaderId;f.stage='answer';state.timerRemaining=question().timer_seconds;state.timerRunning=false;});}
function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function validCore(s){if(!s||s.schemaVersion!==2||s.rulesVersion!=='2.0'||!s.rules||s.rules.auctionMin!==50||s.rules.auctionStep!==50||s.rules.stealFactor!==0.5||typeof s.rules.useBundle5000!=='boolean'||typeof s.rules.debtCardMode!=='boolean'||!B.validateStock(s.physicalStock)||!Array.isArray(s.teams)||s.teams.length<2||s.teams.length>6||![1,2,3].includes(s.currentRound))return false;const ids=new Set(s.teams.map(t=>t.id));if(ids.size!==s.teams.length||!s.teams.every(t=>/^team-[1-6]$/.test(t.id)&&typeof t.name==='string'&&t.name.length<=60&&B.validAmount(t.score)))return false;if(!ids.has(s.activeTeamId)||!Array.isArray(s.answeredIds)||new Set(s.answeredIds).size!==s.answeredIds.length||s.answeredIds.some(id=>!qById[id])||!Array.isArray(s.scoreLog)||!Array.isArray(s.physicalLog)||!s.appliedTransactions||!['board','results'].includes(s.view)||!Number.isSafeInteger(s.serial)||s.serial<0)return false;if(!s.physicalBank||!s.teams.every(t=>{const b=s.physicalBank[t.id];return b&&B.validateStock(b.confirmedComposition)&&[-1,0,1].includes(b.confirmedSign)&&B.validAmount(b.confirmedDebtCard)&&b.confirmedDebtCard>=0;}))return false;if(!s.scoreLog.every(r=>ids.has(r.teamId)&&B.validAmount(r.delta)&&B.validAmount(r.before)&&B.validAmount(r.after)&&r.before+r.delta===r.after&&typeof r.actionId==='string'))return false;const balances=Object.fromEntries(s.teams.map(t=>[t.id,0]));for(const r of s.scoreLog){if(r.before!==balances[r.teamId])return false;balances[r.teamId]=r.after;}if(s.teams.some(t=>balances[t.id]!==t.score)||s.answeredIds.some(id=>typeof s.appliedTransactions[id]!=='string'))return false;if(s.currentQuestionId){const f=s.specialFlow;if(!qById[s.currentQuestionId]||qById[s.currentQuestionId].round!==s.currentRound||s.answeredIds.includes(s.currentQuestionId)||!f||!ids.has(f.openerId)||!ids.has(f.responderId)||!['normal','bag','auction'].includes(f.kind)||!['answer','steal','steal-offer','bag','auction'].includes(f.stage)||!Array.isArray(f.bids)||!f.bids.every(b=>ids.has(b.teamId)&&B.validAmount(b.amount)&&b.amount>=50)||!B.validAmount(f.stake)||f.stake<0||!Array.isArray(f.decisions)||typeof f.actionId!=='string'||f.decisions.length>1||!f.decisions.every(d=>ids.has(d.teamId)&&B.validAmount(d.delta)&&['correct','wrong','pass'].includes(d.result)&&['regular','steal','bag','auction'].includes(d.kind)))return false;}return Number.isSafeInteger(s.timerRemaining)&&s.timerRemaining>=0&&typeof s.revealed==='boolean';}
function validSave(s){return validCore(s)&&Array.isArray(s.history)&&Array.isArray(s.future)&&s.history.length<=30&&s.future.length<=30&&[...s.history,...s.future].every(h=>typeof h.label==='string'&&validCore(h.before)&&validCore(h.after));}

function resume(s=saved){if(!validSave(s)){dialog('Сохранение несовместимо',`<p>Формат не поддерживается или данные повреждены. Исходные данные не изменены.</p><div class="button-row"><button data-act="export-old">Скачать сохранение v2</button><button data-act="legacy">Сохранение v1</button><button data-act="close-dialog">Закрыть</button></div>`);return;}stopClock();state=clone(s);state.timerRunning=false;state.future=state.future||[];B.reconcile(state);persist();close();render();}
function menu(){dialog('Пульт ведущего · СВОЯ BARLEMICA',`<div class="menu-grid"><button data-act="legend">Легенда номиналов Royal Cane</button><button data-act="inventory">Инвентарь и режим долга</button>${state?'<button data-act="physical">Сводный банк и выдача бутылок</button>':''}${legacy?'<button data-act="legacy">Сохранение v1 · экспорт / миграция</button>':''}${location.protocol!=='file:'?'<button data-act="download-offline">↓ Скачать игру для запуска без интернета</button>':''}${state?`<button data-act="backup">↓ Сохранить резервную копию JSON</button><button data-act="import">↑ Загрузить резервную копию</button><button data-act="undo" ${state.history.length?'':'disabled'}>↶ Отменить последнее действие</button><button data-act="redo" ${state.future.length?'':'disabled'}>↷ Повторить действие</button><button data-act="correct-score">± Корректировка счёта</button><button data-act="finish">Посмотреть итоги</button><button class="negative" data-act="reset">Начать новую игру</button>`:`<button data-act="import">↑ Загрузить резервную копию</button>${saved?'<button data-act="export-old">↓ Скачать сохранённые данные</button><button class="negative" data-act="reset">Сбросить сохранение</button>':''}`}<button data-act="help">Как играть и горячие клавиши</button><button data-act="media-status">Проверить изображения</button></div><p class="small">Данные хранятся только в этом браузере. Очистка браузера и режим инкогнито могут стереть ход игры. Перед мероприятием сохраните резервную копию.</p>`);}
function wordmark(){return `<span class="wordmark"><span class="brand-fallback">BARLEMICA</span><img data-brand src="assets/brand/barlemica-logo.svg" alt="BARLEMICA" hidden><small class="brand-note">временный wordmark</small></span>`;}
function restoreActual(actual,log,label){for(const t of state.teams){const real=actual[t.id];if(!real)continue;state.physicalBank[t.id]||={};Object.assign(state.physicalBank[t.id],{confirmedComposition:real.confirmedComposition,confirmedSign:real.confirmedSign,confirmedDebtCard:real.confirmedDebtCard,needsReview:real.needsReview||(/подтверждение|состав|Возврат/.test(label))});}state.physicalLog=log;state.physicalLog.push({kind:'history-review',label,timestamp:new Date().toISOString()});B.reconcile(state);}
function bottleImage(d,small=false){return `<span class="bottle-icon ${small?'small-bottle':''}"><img data-bottle src="assets/bottles/${d.asset}" alt="${d.id==='bundle5000'?'Бутылка с кольцом ×5':d.id==='cap50'?'Жетон':'Условный силуэт бутылки'}"><span class="bottle-fallback" hidden>${d.id==='cap50'?'●':d.id==='bundle5000'?'♟×5':'♟'}</span></span>`;}
function compositionHTML(c,sign=1){if(!B.count(c))return '<span class="zero-composition">0 предметов</span>';return `<div class="bottle-strip ${sign<0?'negative-strip':''}">${B.DENOMS.filter(d=>c[d.id]).map(d=>`<div class="bottle-item">${bottleImage(d)}<strong>${c[d.id]>1?c[d.id]+' × ':''}${fmt(d.points)}</strong></div>`).join('')}</div>`;}
function listOperations(items){return items.length?items.map(x=>`${x.quantity} × ${fmt(x.points)}`).join(' / '):'ничего';}
function physicalDialog(){if(!state)return;B.reconcile(state);dialog('Сводный банк Royal Cane',`<p class="small">Очки — источник истины. Ни подтверждение, ни обмен бутылок не меняют баланс. Раскладывайте каждую команду отдельно.</p><div class="physical-grid">${state.teams.map(t=>{const b=state.physicalBank[t.id];return `<section class="physical-team ${t.score<0?'debt':''}"><div class="physical-team-head"><h3>${esc(t.name)}</h3><strong>${t.score<0?'ДОЛГ ':''}${fmt(t.score)} очков</strong></div><span class="physical-state ${b.pending?'pending':''}">${b.pending?'Ожидает физической сверки':'✓ Бутылки расставлены'}</span><div class="small">Подтверждено на столе ${b.confirmedSign<0?'· зона долга':''}</div>${b.confirmedDebtCard?`<div class="debt-note">Карточка долга −${fmt(b.confirmedDebtCard)}</div>`:compositionHTML(b.confirmedComposition,b.confirmedSign)}<div class="small">Точная целевая раскладка ${b.targetDebtCard?'· на столе карточка долга':''}</div>${compositionHTML(b.targetComposition,b.targetSign)}${instructionsHTML(t.id)}<div class="button-row"><button class="primary" data-act="confirm-bottles" data-id="${t.id}" ${!b.available||!b.pending?'disabled':''}>Бутылки расставлены</button>${B.count(b.confirmedComposition)||b.confirmedDebtCard?`<button data-act="release-bottles" data-id="${t.id}">Вернуть все предметы</button>`:''}<button data-act="record-composition" data-id="${t.id}">Сверить фактический состав</button></div></section>`;}).join('')}</div><button data-act="close-dialog">Вернуться к игре</button>`);}
function legendDialog(){dialog('Легенда Royal Cane',`<p>На экране считаем <b>очки</b>. Бутылки и жетоны на столе только представляют этот баланс.</p><div class="legend-grid">${B.DENOMS.map(d=>`<div class="legend-item">${bottleImage(d)}<strong>${fmt(d.points)} очков</strong><span>${d.label}<br>${d.volume}</span></div>`).join('')}</div><p class="small">Это нейтральные графические силуэты, а не фотографии товарных SKU. ×5 — кольцо на литровой бутылке, не шестой продукт. Фишка 50 нужна для перехвата за половину номинала.</p><p class="small">На каждом столе — маркер команды. Отрицательный баланс показываем отдельно: красный лоток «ДОЛГ» либо выбранная в настройках карточка долга с точным числом. Используйте пустую тару или безопасные демонстрационные образцы.</p><button data-act="close-dialog">Понятно</button>`);}
function inventoryDialog(){if(!state)readDraft();const rules=state?.rules||inventoryDraft.rules,stock=state?.physicalStock||inventoryDraft.stock;dialog('Инвентарь и режим долга',`<p class="small">Укажите общий запас для всех команд. Пустое поле = запас не ограничен в расчёте. Снимите флажок, чтобы отключить номинал. Реальная выдача всё равно требует подтверждения.</p><form id="inventory-form"><div class="inventory-options"><label><input id="use-bundle" type="checkbox" ${rules.useBundle5000?'checked':''}> Набор 5000: литровая бутылка с кольцом ×5</label><label><input id="debt-card" type="checkbox" ${rules.debtCardMode?'checked':''}> Для минуса использовать карточку долга с точным числом</label></div><div class="stock-rows">${B.DENOMS.map(d=>`<label class="stock-row"><input data-stock-enabled="${d.id}" type="checkbox" ${stock[d.id]!==0?'checked':''} aria-label="Доступен номинал ${d.points}"><span><b>${fmt(d.points)} очков</b><small>${d.label} · ${d.volume}</small></span><input data-stock="${d.id}" type="number" min="0" step="1" value="${stock[d.id]??''}" placeholder="Без лимита" aria-label="Общий запас ${d.points}"></label>`).join('')}</div><p class="small">Предметы уже подтверждённые на столах учитываются в общем запасе. При нехватке очки остаются верными, статус — «не синхронизировано».</p><button type="submit" class="primary">${state?'Проверить изменения':'Сохранить настройки'}</button></form>`);}
function saveInventoryForm(){const stock={};for(const d of B.DENOMS){const input=$(`[data-stock="${d.id}"]`),enabled=$(`[data-stock-enabled="${d.id}"]`).checked;const n=input.value.trim()===''?null:Number(input.value);if(n!==null&&(!Number.isSafeInteger(n)||n<0))return toast('Запас — целое неотрицательное число либо пустое поле');stock[d.id]=enabled?n:0;}const rules={...B.DEFAULT_RULES,useBundle5000:$('#use-bundle').checked,debtCardMode:$('#debt-card').checked};if(!state){inventoryDraft={rules,stock};close();toast('Настройки реквизита сохранены');return;}if(state.currentQuestionId)return toast('Завершите текущий вопрос перед изменением инвентаря');for(const d of B.DENOMS){const used=state.teams.reduce((n,t)=>n+(state.physicalBank[t.id].confirmedComposition[d.id]||0),0);if(stock[d.id]!==null&&stock[d.id]<used)return toast('На столах уже подтверждено '+used+' предметов номиналом '+d.points+'. Сначала верните их в банк.');}inventoryPending={rules,stock};confirmDialog('Изменить правила реквизита?','Очки сохранятся. Все целевые раскладки будут пересчитаны; может потребоваться физическая сверка.','inventory-confirm');}
function recordComposition(id){const b=state.physicalBank[id];dialog('Фактический состав: '+esc(team(id).name),`<p class="small">Запишите уже стоящие на столе предметы. Очки не меняются. Если сумма отличается от счёта, появится точная инструкция сверки.</p><form id="physical-record-form" data-id="${id}"><select id="record-sign" aria-label="Зона стола"><option value="1" ${b.confirmedSign>=0?'selected':''}>Положительная зона</option><option value="-1" ${b.confirmedSign<0?'selected':''}>Красный лоток ДОЛГ</option></select><div class="stock-rows">${B.DENOMS.map(d=>`<label class="stock-row record-row"><span>${fmt(d.points)} очков</span><input data-record="${d.id}" type="number" min="0" step="1" value="${b.confirmedComposition[d.id]||0}" aria-label="На столе ${d.points}"></label>`).join('')}</div><button class="primary" type="submit">Подтвердить состав</button></form>`);}
function savePhysicalRecord(form){const id=form.dataset.id,composition={};for(const d of B.DENOMS){const n=Number($(`[data-record="${d.id}"]`).value);if(!Number.isSafeInteger(n)||n<0)return toast('Количество предметов должно быть целым');if(n)composition[d.id]=n;}const sign=B.count(composition)?Number($('#record-sign').value):0;for(const d of B.DENOMS){const used=state.teams.filter(t=>t.id!==id).reduce((n,t)=>n+(state.physicalBank[t.id].confirmedComposition[d.id]||0),0)+(composition[d.id]||0);if(state.physicalStock[d.id]!=null&&used>state.physicalStock[d.id])return toast('Этот состав превышает общий запас '+d.points);}inventoryPending={record:true,id,composition,sign};confirmDialog('Зафиксировать физический состав?',`${esc(team(id).name)}: на столе ${fmt(B.sum(composition)*sign)} очков в предметах. Числовой баланс ${fmt(team(id).score)} не изменится.`,'record-confirm');}
function skipEffect(){clearTimeout(effectTimer);const el=$('#result-effect');if(el)el.remove();document.querySelectorAll('[data-score-team]').forEach(el=>{const t=state?.teams.find(t=>t.id===el.dataset.scoreTeam);if(t)el.textContent=t.score<0?'−'+fmt(-t.score):fmt(t.score);});}
function legacyDialog(){dialog('Сохранение предыдущей версии',`<p>Найдено состояние v1. Оно сохранится в своём ключе и не будет перезаписано. Сначала можно скачать резервную копию, затем явно перенести игру в v2.</p><p class="small">Баланс и все ставки должны быть кратны 50. История Undo v2 начнётся заново; исходная история v1 останется в старом сохранении. Незавершённые начисления текущего вопроса будут перенесены как отложенные решения.</p><div class="button-row"><button data-act="export-legacy">Скачать v1 JSON</button><button class="primary" data-act="migrate-ask">Перенести в v2</button><button data-act="close-dialog">Закрыть</button></div>`);}
function migrateLegacy(){try{if(!legacy||legacy.schemaVersion!==1||!Array.isArray(legacy.teams)||legacy.teams.length<2||legacy.teams.length>6||!legacy.teams.every(t=>B.validAmount(t.score)))throw new Error('Счета v1 не кратны 50 или формат несовместим. Экспортируйте v1 и начните новую игру.');const old=clone(legacy);if(old.specialFlow&&(!B.validAmount(old.specialFlow.stake)||old.specialFlow.bids.some(b=>!B.validAmount(b.amount))))throw new Error('В v1 есть ставка не кратная 50. Перенос без округления невозможен.');let scoreLog=[],running=Object.fromEntries(old.teams.map(t=>[t.id,0]));for(const [i,r] of old.scoreLog.entries()){if(!B.validAmount(r.delta))throw new Error('Журнал v1 содержит некратную 50 поправку');const before=running[r.teamId]||0,after=before+r.delta;running[r.teamId]=after;scoreLog.push({questionId:r.questionId||null,actionId:r.questionId?'legacy:'+r.questionId:'legacy:manual:'+i,teamId:r.teamId,basePoints:qById[r.questionId]?.points||0,kind:r.kind==='normal'?'regular':r.kind==='correction'?'manual':r.kind||'regular',stake:r.kind==='auction'?Math.abs(r.delta):null,delta:r.delta,before,after,reason:'Перенос из v1',result:r.result||'manual',timestamp:r.at||old.startedAt});}state={...old,schemaVersion:2,rulesVersion:'2.0',rules:clone(B.DEFAULT_RULES),scoreLog,physicalBank:{},physicalStock:Object.fromEntries(B.DENOMS.map(d=>[d.id,null])),physicalLog:[],appliedTransactions:Object.fromEntries(old.answeredIds.map(id=>[id,'legacy:'+id])),serial:scoreLog.length,history:[],future:[],timerRunning:false};if(state.specialFlow){const f=state.specialFlow;f.actionId='migrated:'+state.currentQuestionId;f.decisions=[];if(['steal','steal-offer'].includes(f.stage)){const r=state.scoreLog[state.scoreLog.length-1];if(r&&r.questionId===state.currentQuestionId){state.scoreLog.pop();team(r.teamId).score-=r.delta;f.decisions.push({teamId:r.teamId,delta:r.delta,result:r.result,kind:r.kind});}}}B.reconcile(state);if(!validSave(state)){state=null;throw new Error('Не удалось безопасно перенести формат v1. Исходное сохранение не изменено.');}persist();close();render();toast('Перенос выполнен. Сохранение v1 оставлено нетронутым. Проверьте банк.');}catch(e){state=null;toast(e.message);}}

function operationRows(items){return items.map(item=>{const d=B.DENOMS.find(x=>x.id===item.id);return `<li class="operation-item"><span class="operation-quantity">${item.quantity}<small>шт.</small></span>${bottleImage(d)}<span class="operation-product"><b>${esc(d.id==='bundle5000'?'Бутылка с кольцом ×5':d.label)}</b><span>${fmt(d.points)} очков за предмет</span></span></li>`;}).join('');}
function instructionsHTML(id){const b=state.physicalBank[id],p=B.plan(state,id),t=team(id);return `<div class="physical-instructions"><div class="operation-grid"><section class="operation-group take-back"><h4>1. Забрать у команды</h4>${p.remove.length?`<ul>${operationRows(p.remove)}</ul>`:'<p class="operation-empty">Ничего забирать не нужно</p>'}${p.removeDebtCard?'<p class="zone-instruction">Убрать прежнюю карточку долга</p>':''}${p.changeZone&&b.confirmedSign<0?'<p class="zone-instruction">Убрать прежний красный маркер долга</p>':''}</section><section class="operation-group hand-out"><h4>2. ${p.sign<0&&!p.debtCard?'Положить в лоток «ДОЛГ»':'Выдать команде'}</h4>${p.add.length?`<ul>${operationRows(p.add)}</ul>`:p.debtCard?`<p class="debt-card-instruction">Карточка долга <b>−${fmt(p.debtCard)} очков</b></p>`:'<p class="operation-empty">Ничего выдавать не нужно</p>'}</section></div>${p.sign<0?`<div class="debt-note"><b>ДОЛГ −${fmt(Math.abs(t.score))} очков</b><span>${p.debtCard?'На столе — карточка с этим точным числом.':'Все перечисленные предметы разместить отдельно, в красной зоне долга.'}</span></div>`:p.sign===0?'<div class="zero-instruction">После возврата предметов оставьте на столе карточку «0».</div>':''}${!p.available?'<div class="stock-warning"><b>Не хватает бутылок / жетонов. Выдача пока недоступна.</b><span>Счёт уже сохранён. Уточните запас или верните предметы других команд в банк.</span></div>':''}<div class="physical-total"><span>На столе в итоге</span><strong>${t.score<0?'ДОЛГ ':''}${fmt(t.score)} очков</strong></div></div>`;}
function resultPanel(rows){return `<div id="result-effect" data-result-panel><p class="result-intro">Очки сохранены. Выполните указанные действия с реквизитом и подтвердите выдачу.</p><div class="result-grid ${rows.length>1?'two-teams':''}">${rows.map(r=>{const b=state.physicalBank[r.teamId],confirmed=b.confirmedDebtCard?-b.confirmedDebtCard:B.sum(b.confirmedComposition)*b.confirmedSign,stale=b.pending&&confirmed!==r.before;return `<section class="effect-team ${r.delta<0?'penalty':''}" data-result-team="${esc(r.teamId)}"><div class="result-team-heading"><h3>${esc(r.name)}</h3><span class="result-delta">${r.delta>0?'+':''}${fmt(r.delta)} очков</span></div><div class="result-score"><span><small>Было</small><b>${fmt(r.before)}</b></span><span class="result-arrow" aria-hidden="true">→</span><span><small>Стало</small><b>${fmt(r.after)}</b></span></div>${!b.pending?'<div class="result-confirmed">✓ Реквизит этой команды уже подтверждён</div>':`${stale?`<div class="unconfirmed-notice"><b>На столе подтверждено только ${fmt(confirmed)} очков.</b><span>Инструкция учитывает весь неполученный реквизит до общего счёта ${fmt(team(r.teamId).score)}. Если предметы уже выданы, сначала укажите фактический состав.</span><button data-act="record-composition" data-id="${esc(r.teamId)}">Предметы уже на столе →</button></div>`:''}${instructionsHTML(r.teamId)}`}<button class="primary confirm-result" data-act="confirm-result" data-id="${esc(r.teamId)}" ${!b.pending||!b.available?'disabled':''}>${b.pending?'Подтвердить: реквизит выдан':'✓ Выдача подтверждена'}</button></section>`;}).join('')}</div><div class="result-footer"><span>Подтверждайте после физической выдачи. Можно продолжить игру и сверить позже.</span><div class="button-row"><button data-act="undo">↶ Отменить оценку</button><button data-act="physical">Весь банк</button><button class="primary" data-act="close-dialog">${rows.every(r=>!state.physicalBank[r.teamId].pending)?'Готово · к полю →':'К полю · выдать позже →'}</button></div></div></div>`;}
function showResult(rows,animate=true){skipEffect();if(!rows.some(r=>r.delta))return toast('Вопрос завершён без изменения очков');resultRows=clone(rows);dialog('Результат и выдача реквизита',resultPanel(rows));const panel=$('#result-effect');if(animate)panel.classList.add('result-enter');}

const handlers={
'download-offline':()=>{const a=document.createElement('a');a.href='Barlemica-2026-Royal-Cane.zip';a.download='Barlemica-2026-Royal-Cane.zip';a.click();},'close-dialog':close,'fullscreen':async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch(e){toast('Полный экран недоступен в этом окне. Откройте сайт в отдельной вкладке.');}},'menu':menu,
'add-team':()=>{readDraft();if(draft.length<6)draft.push('Команда '+(draft.length+1));render();},'remove-team':b=>{readDraft();draft.splice(Number(b.dataset.i),1);render();},
'start':()=>{readDraft();if(saved)confirmDialog('Начать новую игру?','Сохранённая игра будет заменена. Резервную копию можно скачать через меню.','new-confirm');else newGame();},'new-confirm':newGame,'resume':()=>resume(),
'question':b=>openQuestion(b.dataset.id),'active-team':b=>{if(!state.currentQuestionId)action('Смена выбирающей команды',()=>{state.activeTeamId=b.dataset.id;});},
'reveal':reveal,'timer':toggleTimer,'timer-reset':()=>{if(!state?.currentQuestionId)return;stopClock();action('Перезапуск таймера',()=>{state.timerRemaining=state.specialFlow.stage==='auction'?30:question().timer_seconds;state.timerRunning=false;});},'timer-add':()=>{if(state?.currentQuestionId)action('Добавление времени',()=>{state.timerRemaining+=10;});},
'judge':b=>judge(b.dataset.result),'complete':()=>{if(state.specialFlow?.stage==='steal-offer')action('Завершение вопроса',finalize);},
'steal':b=>{if(state.specialFlow.stage!=='steal-offer'||b.dataset.id===state.specialFlow.openerId)return;action('Перехват вопроса',()=>{state.specialFlow.stage='steal';state.specialFlow.responderId=b.dataset.id;state.timerRemaining=question().timer_seconds;});},
'bag-to':b=>{if(state.specialFlow.stage!=='bag'||b.dataset.id===state.specialFlow.openerId)return;action('Передача сиропа',()=>{state.specialFlow.responderId=b.dataset.id;state.specialFlow.stage='answer';});},
'cancel-question':()=>{if(!['bag','auction'].includes(state.specialFlow?.stage))return;stopClock();action('Отмена специального вопроса',()=>{state.currentQuestionId=null;state.specialFlow=null;state.timerRunning=false;});},'auction-end':auctionEnd,
'undo':()=>{close();undo();},'redo':()=>{close();redo();},
'round':b=>{if(Number(b.dataset.r)===state.currentRound)return;confirmDialog('Перейти в другой раунд?','Незаданные вопросы сохранятся. Вы сможете вернуться к ним позже.','round-confirm',`data-r="${b.dataset.r}"`);},'next-round':()=>confirmDialog('Перейти к следующему раунду?','Счёт команд сохранится. Незаданные вопросы останутся на поле.','round-confirm',`data-r="${state.currentRound+1}"`),
'round-confirm':b=>{if(state.currentQuestionId)return;close();action('Переход между раундами',()=>{state.currentRound=Number(b.dataset.r);});},
'finish':()=>{if(state?.currentQuestionId)return toast('Сначала завершите текущий вопрос');if(state)confirmDialog('Показать итоги игры?','Сохраним текущий счёт. К игровому полю можно будет вернуться.','finish-confirm');},'finish-confirm':()=>{close();action('Переход к итогам',()=>{state.view='results';});},'return-board':()=>action('Возврат к полю',()=>{state.view='board';}),
'export-results':()=>download('results.json',{event:'СВОЯ BARLEMICA',rulesVersion:state.rulesVersion,rules:state.rules,physicalBank:state.physicalBank,physicalStock:state.physicalStock,physicalLog:state.physicalLog,startedAt:state.startedAt,exportedAt:new Date().toISOString(),round:state.currentRound,answeredIds:state.answeredIds,ranking:[...state.teams].sort((a,b)=>b.score-a.score).map(t=>({...t,rank:1+state.teams.filter(other=>other.score>t.score).length,tied:state.teams.filter(other=>other.score===t.score).length>1})),scoreLog:state.scoreLog,appliedTransactions:state.appliedTransactions}),
'backup':()=>download('barlemica-backup.json',state),'export-old':()=>download('barlemica-saved.json',saved),'import':()=>$('#import-file').click(),
'reset':()=>confirmDialog('Сбросить игру?','Текущий ход игры будет удалён из этого браузера. Сохраните резервную копию перед сбросом.','reset-confirm'),
'reset-confirm':()=>{stopClock();skipEffect();try{localStorage.removeItem(KEY);}catch(e){}state=null;saved=null;close();render();},
'host-note':()=>{if(!state.revealed)return;const q=question();dialog('Заметка ведущему',`<p class="warning">Этот блок виден на общем экране. Открывайте его, когда заметку можно показать участникам.</p><button class="primary" data-act="show-note">Открыть заметку</button>`);},
'show-note':()=>{if(!state.revealed)return;const q=question();dialog('Заметка ведущему',`<p>${esc(q.host_note||'Дополнительных заметок нет.')}</p><p class="small">${state.revealed?'Допустимые ответы: '+esc(q.accepted_answers.join(' / ')):'Ответ пока скрыт. Допустимые варианты появятся после раскрытия.'}</p>`);},
 'correct-score':()=>{if(state.currentQuestionId)return toast('Сначала завершите вопрос');dialog('Корректировка очков',`<p>Поправка к счёту: ±50, ±100 и т. д. Причина обязательна.</p><form id="correction-form"><div class="form-row"><select id="correction-team" aria-label="Команда">${state.teams.map(t=>`<option value="${esc(t.id)}">${esc(t.name)} · ${fmt(t.score)}</option>`).join('')}</select><input id="correction-value" type="number" min="-1000000000" max="1000000000" step="50" required placeholder="Изменение, например −50" aria-label="Изменение счёта"><input id="correction-reason" maxlength="200" required placeholder="Причина корректировки" aria-label="Причина корректировки"></div><button class="primary" type="submit">Продолжить</button></form>`);},
 'correction-1':()=>{if(!correctionPending)return;const c=correctionPending;confirmDialog('Окончательно изменить счёт?',`${esc(team(c.id).name)}: ${fmt(team(c.id).score)} → ${fmt(team(c.id).score+c.delta)}. Причина: ${esc(c.reason)}`,'correction-2');},
 'correction-2':()=>{if(!correctionPending)return;const c=correctionPending;correctionPending=null;close();action('Ручная корректировка очков',()=>{const t=team(c.id),before=t.score;t.score+=c.delta;const row={questionId:null,actionId:'manual:'+(++state.serial),teamId:t.id,basePoints:0,kind:'manual',stake:null,delta:c.delta,before,after:t.score,reason:c.reason,timestamp:new Date().toISOString()};state.scoreLog.push(row);animationRows=[{...row,name:t.name}];});},
'help':()=>dialog('Всё просто',`<p>Команда выбирает категорию и стоимость. Прочитайте вопрос, запустите таймер. Раскройте ответ и оцените его: верно +номинал, неверно −номинал, без ответа 0. После ошибки или паса доступен один перехват за половину стоимости.</p><p>«Сироп в мешке» нужно передать другой команде. В аукционе побеждает наибольшая ставка. Версия 2.0: минимум и шаг ставки — 50 очков, максимум — положительный баланс. Правило v1 о ставках от 1 очка переопределено конфигурацией приложения. В обоих случаях следующий вопрос выбирает инициатор.</p><p><span class="key">Space</span> показать ответ<br><span class="key">T</span> старт / пауза таймера<br><span class="key">R</span> перезапуск таймера<br><span class="key">U</span> отмена последнего действия<br><span class="key">F</span> полный экран</p><p class="small">Таймер не раскрывает ответ автоматически. Можно завершить игру после второго раунда или вернуться к полю из итогов.</p>`),
'media-status':async()=>{const art=D.questions.filter(q=>q.media_type==='artwork');const checks=await Promise.all(art.map(q=>new Promise(resolve=>{const img=new Image();const timeout=setTimeout(()=>resolve(false),5000);img.onload=()=>{clearTimeout(timeout);resolve(true);};img.onerror=()=>{clearTimeout(timeout);resolve(false);};img.src='assets/art/'+q.id.toLowerCase()+'.jpg';})));dialog('Изображения к вопросам',`<p>Локальных репродукций готово: ${checks.filter(Boolean).length} из ${art.length}.</p><div class="small">${art.map((q,i)=>`${checks[i]?'✓':'×'} ${esc(q.id)}`).join('<br>')}</div><p class="small">Изображения загружаются только из локальной папки. Если файл отсутствует, показывается нейтральное предупреждение. Две недостающие репродукции необходимо подготовить до полноценного тура «Искусство».</p>`);}
};
Object.assign(handlers,{
 'confirm-result':b=>{if(!resultRows||!state.physicalBank[b.dataset.id]?.pending)return;const rows=clone(resultRows),id=b.dataset.id;action('Физическое подтверждение выдачи',()=>{const before=clone(state.physicalBank[id]);B.confirm(state,id);state.physicalLog.push({kind:'confirm',teamId:id,before,after:clone(state.physicalBank[id]),timestamp:new Date().toISOString()});});showResult(rows,false);},'legend':legendDialog,'physical':()=>{skipEffect();physicalDialog();},'inventory':inventoryDialog,'skip-effect':skipEffect,
 'inventory-confirm':()=>{if(!inventoryPending||inventoryPending.record)return;const p=inventoryPending;inventoryPending=null;close();action('Изменение инвентаря',()=>{state.rules=p.rules;state.physicalStock=p.stock;state.physicalLog.push({kind:'inventory',rules:clone(p.rules),stock:clone(p.stock),timestamp:new Date().toISOString()});});physicalDialog();},
 'confirm-bottles':b=>{const id=b.dataset.id;action('Физическое подтверждение выдачи',()=>{const before=clone(state.physicalBank[id]);B.confirm(state,id);state.physicalLog.push({kind:'confirm',teamId:id,before,after:clone(state.physicalBank[id]),timestamp:new Date().toISOString()});});physicalDialog();},
 'release-bottles':b=>confirmDialog('Вернуть все предметы в банк?',`Физически уберите со стола ${esc(team(b.dataset.id).name)} все предметы и карточку долга. Очки не меняются. Подтвердите только после выполнения.`,'release-confirm',`data-id="${b.dataset.id}"`),
 'release-confirm':b=>{action('Возврат физического реквизита',()=>{const bank=state.physicalBank[b.dataset.id],before=clone(bank);bank.confirmedComposition={};bank.confirmedSign=0;bank.confirmedDebtCard=0;bank.needsReview=false;state.physicalLog.push({kind:'release',teamId:b.dataset.id,before,timestamp:new Date().toISOString()});});physicalDialog();},
 'record-composition':b=>recordComposition(b.dataset.id),
 'record-confirm':()=>{if(!inventoryPending?.record)return;const p=inventoryPending;inventoryPending=null;action('Сверка фактического состава',()=>{const b=state.physicalBank[p.id];b.confirmedComposition=p.composition;b.confirmedSign=p.sign;b.confirmedDebtCard=0;b.needsReview=false;state.physicalLog.push({kind:'record',teamId:p.id,composition:p.composition,sign:p.sign,timestamp:new Date().toISOString()});});physicalDialog();},
 'legacy':legacyDialog,'export-legacy':()=>download('barlemica-v1-original.json',legacy),
 'migrate-ask':()=>confirmDialog('Перенести сохранение v1?',`${saved?'Текущее сохранение v2 будет заменено. ':''}Баланс не округляется. История v1 сохранится отдельно. Физический реквизит потребуется сверить.`,'migrate-confirm'),'migrate-confirm':migrateLegacy,
 'tie-break':()=>dialog('Нейтральный тай-брейк',`<p>Назовите без повторов названия барных инструментов. Ведущий задаёт одинаковое время всем командам с равными очками и оценивает устные ответы.</p><p class="small">Это отдельное устное задание вне банка 90 вопросов. Баланс не меняется, официальный рейтинг сохраняет ничью. Любое дополнительное решение ведущего не меняет очки сайта.</p><button data-act="close-dialog">Вернуться к итогам</button>`)
});
document.addEventListener('click',e=>{const b=e.target.closest('button[data-act]');if(!b||b.disabled)return;handlers[b.dataset.act]?.(b);});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='bid-form')bid();if(e.target.id==='inventory-form')saveInventoryForm();if(e.target.id==='physical-record-form')savePhysicalRecord(e.target);if(e.target.id==='correction-form'){const id=$('#correction-team').value,delta=Number($('#correction-value').value),reason=$('#correction-reason').value.trim();if(!B.validAmount(delta)||!delta||!reason)return toast('Нужны ненулевая поправка кратно 50 и причина');if(!B.validAmount(team(id).score+delta))return toast('Слишком большой баланс');correctionPending={id,delta,reason};confirmDialog('Подтвердить корректировку?',`${esc(team(id).name)}: ${delta>0?'+':''}${fmt(delta)} очков. ${esc(reason)}`,'correction-1');}});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>5000000)throw Error('size');const imported=JSON.parse(await f.text());if(!validSave(imported))throw Error('schema');window.pendingImport=imported;confirmDialog('Восстановить резервную копию?','Текущая игра будет заменена данными из выбранного файла.','import-confirm');}catch(err){toast('Не удалось загрузить: повреждённый или несовместимый файл игры');}});
handlers['import-confirm']=()=>{const s=window.pendingImport;for(const b of Object.values(s.physicalBank))b.needsReview=true;resume(s);delete window.pendingImport;toast('Игра восстановлена. Сверьте физический реквизит со столами.');};
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.repeat||e.target.closest?.('input,textarea,select,[contenteditable="true"]'))return;if($('#dialog').open)return;const k=e.key.toLowerCase();if(k==='f'){e.preventDefault();handlers.fullscreen();}if(!state)return;if(k===' '){e.preventDefault();reveal();}if(k==='t'){e.preventDefault();toggleTimer();}if(k==='r'&&state.currentQuestionId){e.preventDefault();handlers['timer-reset']();}if(k==='u'){e.preventDefault();undo();}});
$('#dialog').addEventListener('cancel',()=>{skipEffect();resultRows=null;});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state?.timerRunning){stopClock();state.timerRunning=false;persist();syncTimer();}});
render();if(!saved&&legacy)legacyDialog();if(saved)dialog('Вернёмся к игре?',`<p>На этом устройстве есть сохранённый ход игры. Продолжить с того же места?</p><div class="button-row"><button class="primary" data-act="resume">Продолжить</button><button data-act="close-dialog">На стартовый экран</button></div>`);if(!storageOK)toast('Локальное хранилище недоступно. Используйте резервные копии JSON.');
})();
